        [Browsable(true), Category("Appearance"), Description("Transparent color for the Image property")]        public Color TransparentColor {            get;            set;        }       TransparentColor = Color.FromArgb(192, 192, 192);         protected override void OnPaint(PaintEventArgs e) {            //e.Graphics.Clear(BackColor);            if (this.Image != null)                try {                    Bitmap bmp = ((Bitmap)this.Image);                    bmp.MakeTransparent(TransparentColor);                    int x = (this.Width - bmp.Width) / 2;                    int y = (this.Height - bmp.Height) / 2;                    e.Graphics.DrawImage(bmp, x, y);                } catch {                    // Would only happens as a cast exception if used                    // a non-Bitmap for this.Image                }            base.OnPaint(e);        }        protected override void OnPaint(PaintEventArgs e) {            e.Graphics.Clear(BackColor);        }        protected override void OnPaintBackground(PaintEventArgs e) {            e.Graphics.Clear(BackColor);        }